package com.nigson.integration.carrier;
import java.net.*;
import java.net.http.*;
import java.time.Duration;
import java.util.*;
import java.util.function.Function;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.integration.provider.PrivateHttp;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;
/** Fixed private result destination; an uncertain acknowledgement retains the original receipt. */
public final class CarrierCancellationResultClient {
 private final URI base;private final HttpClient http;private final Function<PrivateWorkload.Route,String> credentials;
 private static final tools.jackson.databind.json.JsonMapper JSON=tools.jackson.databind.json.JsonMapper.builder(tools.jackson.core.json.JsonFactory.builder().enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(tools.jackson.core.StreamReadConstraints.builder().maxNestingDepth(8).maxStringLength(65536).build()).build()).enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
 public CarrierCancellationResultClient(String env,String endpoint,Function<PrivateWorkload.Route,String> credentials){if(env==null||!Set.of("local","test","dev","qa","stage","prod").contains(env)||endpoint==null||endpoint.length()>2048)throw new IllegalArgumentException("PRIVATE_TARGET_REQUIRED");URI uri=URI.create(endpoint);if(uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||!Set.of("","/").contains(uri.getPath()))throw new IllegalArgumentException("PRIVATE_TARGET_REQUIRED");if(Set.of("local","test").contains(env)){if(!"http".equals(uri.getScheme())||!Set.of("commerce","127.0.0.1","localhost").contains(uri.getHost()))throw new IllegalArgumentException("LOCAL_PRIVATE_TARGET_REQUIRED");}else if(!"https".equals(uri.getScheme())||!uri.getHost().endsWith(".internal")||uri.getPort()!=-1)throw new IllegalArgumentException("APPROVED_PRIVATE_HTTPS_REQUIRED");base=uri;this.credentials=Objects.requireNonNull(credentials);http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();}
 public void acknowledge(CarrierCancellationValues.Receipt receipt){if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");try{var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-199")).findFirst().orElseThrow();String token=credentials.apply(route);if(token==null||!token.matches("[A-Za-z0-9._~+/-]{1,16384}={0,2}"))throw ApiValues.invalid();var sorted=new TreeMap<String,String>();EventCodec.JSON.valueToTree(receipt).properties().forEach(e->sorted.put(e.getKey(),e.getValue().asString()));var request=HttpRequest.newBuilder(base.resolve(route.path())).timeout(Duration.ofSeconds(5)).header("Authorization","Bearer "+token).header("Accept","application/json").header("Content-Type","application/json").header("X-Correlation-ID",receipt.commandId().toString()).header("Idempotency-Key",receipt.commandId().toString()).POST(HttpRequest.BodyPublishers.ofByteArray(EventCodec.JSON.writeValueAsBytes(sorted))).build();var response=PrivateHttp.send(http,request,65536,Duration.ofSeconds(6));if(response.statusCode()!=200||response.headers().allValues("Content-Type").size()!=1||!"application/json".equals(response.headers().firstValue("Content-Type").orElse("").split(";",2)[0].strip()))throw ApiValues.invalid();var body=JSON.readTree(response.body());if(!body.isObject()||!body.propertyNames().equals(Set.of("id","shipmentId","state","version","shipmentVersion","errorCode"))||!receipt.cancellationId().equals(ApiValues.uuid(body.path("id").asString()))||!receipt.shipmentId().equals(ApiValues.uuid(body.path("shipmentId").asString()))||!(receipt.state().equals(body.path("state").asString())||receipt.state().equals("UNKNOWN")&&Set.of("CANCELLED","REJECTED").contains(body.path("state").asString())))throw ApiValues.invalid();for(String name:List.of("version","shipmentVersion"))if(!body.path(name).isIntegralNumber()||!body.path(name).canConvertToLong()||body.path(name).asLong()<0)throw ApiValues.invalid();if(!body.path("errorCode").isNull()&&(!body.path("errorCode").isString()||!CarrierCancellationValues.REASONS.contains(body.path("errorCode").asString())))throw ApiValues.invalid();}catch(RuntimeException unavailable){throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}}
}
